--- 选择器任务类似于一个 "或 "操作。只要它的一个子任务返回成功，它就会返回成功。
--- 如果一个子任务返回失败，那么它将依次运行下一个任务。
--- 如果没有子任务返回成功，那么它将返回失败

------------ import ------------
local Composite = import("Frame.AI.BT.Composites.Composite")
------------ import ------------

------------ define ------------

------------ define ------------

---@class Selector
local Selector = Class("Selector", Composite)

function Selector:__init(abortType)
    Composite.__init(self)
    
    self._abortType = abortType or Composite.AbortTypes.None
    
end

function Selector:__delete()

end

function Selector:Update(context)
    --- 首先，如果我们不在第一个子节点身上，我们就处理条件性中止
    if not Composite.IsFirstIndex(self) then
        self:HandleConditionalAborts(context)
    end
    
    local current = self._children[self._currentChildIndex]
    local status  = current:Tick(context)
    --- 如果子节点成功了或者还在跑，就提前返回
    if status ~= Composite.TaskStatus.Failure then
       return status 
    end
    
    self._currentChildIndex = self._currentChildIndex + 1
    
    --- 如果子节点再最后一个，这意味着整个事情失败了
    if self._currentChildIndex > #self._children then
        Composite.ResetCurrentIndex(self)
        return Composite.TaskStatus.Failure
    end
    
    return Composite.TaskStatus.Running
    
end

function Selector:HandleConditionalAborts(context)
    --- 检查任何较低优先级的任务，看它们是否改变为成功
    if self._hasLowerPriorityConditionalAbort then
        Composite.UpdateLowerPriorityAbortConditional(self, context, Composite.TaskStatus.Failure)
    end

    if Composite.BTUtils.HasAbortType(self._abortType, Composite.AbortTypes.Self) then
        Composite.UpdateSelfAbortConditional(self, context, Composite.TaskStatus.Failure)
    end
end


return Selector
 